INSERT INTO private.career_event_templates(event_key,source,title,body,choices) VALUES
('social_media_tone','Redes sociais','O que você quer publicar?','Seu assessor deixou três ideias prontas. Você também pode optar por uma mensagem simples e evitar transformar a publicação em assunto.','[{"key":"team","label":"“Semana de trabalho com o grupo. Seguimos juntos.”","result":"A publicação reforçou uma imagem ligada ao coletivo.","effects":{"fans":2,"locker":3,"board":2,"image":1,"media":-1}},{"key":"ambitious","label":"“Trabalhando em silêncio. Meu objetivo é chegar ao topo.”","result":"A mensagem aumentou a atenção sobre sua ambição pessoal.","effects":{"media":3,"image":4,"agent":2,"fans":1,"locker":-1,"pressure":3,"ambition":2}},{"key":"provocative","label":"“Podem falar. Eu sei o que sou capaz de fazer.”","result":"A frase ganhou repercussão e dividiu a reação em torno do seu nome.","effects":{"media":6,"fans":4,"image":5,"coach":-2,"board":-2,"locker":-2,"pressure":5,"ego":3}},{"key":"simple","label":"“Mais um dia. 🙏”","result":"A publicação passou quase sem ruído e manteve sua exposição controlada.","effects":{"media":-1,"fans":1,"image":1,"pressure":-1}}]')
